There exists a universal constant $c$ such that for any log-concave density $p$ in $\ensuremath{\mathbb{R}}^{\ensuremath{d}}$ and any integer $\ell \geq 1$, we have
  \begin{align}

    \psi(p) \geq \frac{1}{\left[ c \cdot \ell \left( \log(\ensuremath{d})+1 \right) \right]^{\ell/2} \ensuremath{d}^{16/\ell} \cdot \sqrt{\rho\left( p \right)}}
  \end{align}
  where $\rho\left( p \right)$ is the spectral norm of the covariance matrix of $p$.

There exists a universal constant $c$ such that for any log-concave density $p$ in $\ensuremath{\mathbb{R}}^{\ensuremath{d}}$ with compact support and any integer $\ell \geq 1$, we have
  \begin{align}

    \psi(p) \geq \frac{1}{\left[ c \cdot \ell \left( \log(\ensuremath{d})+1 \right) \right]^{\ell/2} \ensuremath{d}^{16/\ell} \cdot \sqrt{\rho\left( p \right)}}.
  \end{align}

Suppose that $\psi_k \geq \frac{1}{\alpha k^\beta}$ for all $k \leq \ensuremath{d}$ for some $0 \leq \beta \leq \frac{1}{2}$ and $\alpha \geq 1$, take $q = \lceil \frac{1}{\beta} \rceil + 1$, there exists a universal constant $c$ such that we have
  \begin{align*}
    \psi_{\ensuremath{d}} \geq \frac{1}{c \cdot q^{1/2} \alpha \log(\ensuremath{d})^{1/2} \ensuremath{d}^{\beta - \beta / (8q) }}.
  \end{align*}

Under the same assumptions of Lemma~3, for any measurable subset $E$ of $\ensuremath{\mathbb{R}}^{\ensuremath{d}}$ with $p(E) = \frac{1}{2}$ and $t > 0$, the solution $p_t$ of the SDE~(9) satisfies
  \begin{align*}
    \ensuremath{{\mathbb{P}}}\left( \frac{1}{4} \leq p_t(E) \leq \frac{3}{4} \right) \geq \frac{9}{10} - \ensuremath{{\mathbb{P}}}\left( \int_0^t \left\| A^{-1/2} A_t A^{-1/2}\right\|_{2} ds \geq \frac{1}{64} \right).
  \end{align*}

Given a density $p$ in $\ensuremath{\mathbb{R}}^{\ensuremath{d}}$ with compact support with covariance $A$ and $A$ is invertible, then the SDE~(8) is well defined and it has a unique solution on the time interval $[0, T]$, for any time $T > 0$. Additionally, for any $x \in \ensuremath{\mathbb{R}}^{\ensuremath{d}}$, $p_t(x)$ is a martingale with
  \begin{align}

    dp_t(x) = \left( x - \mu_t \right)^\top A^{-1/2} dW_t p_t(x).
  \end{align}

In addition to the same assumptions of Lemma~3, if $\psi_k \geq \frac{1}{\alpha k^\beta}$ for all $k \leq \ensuremath{d}$ for some $0 < \beta \leq \frac{1}{2}$ and $\alpha \geq 1$, then there exists a universal constant $c$ such that for $q = \lceil \frac{1}{\beta} \rceil + 1$, $\ensuremath{d} \geq 3$ and $T_2 = \frac{1}{ c \cdot q \alpha^2\log(\ensuremath{d}) \ensuremath{d}^{2\beta - \beta/(4q)}}$, we have
  \begin{align*}
    \ensuremath{{\mathbb{P}}}\left( \int_{0}^{T_2} \left\| A^{-1/2} A_t A^{-1/2}\right\|_{2} dt \geq \frac{1}{64} \right) < \frac{4}{10}.
  \end{align*}

Under the same assumptions of Lemma~6, using the following transformation
  \begin{align*}
    h: \ensuremath{\mathbb{R}}_+ &\rightarrow \ensuremath{\mathbb{R}} \\
    a &\mapsto -(a+1)^{-1/q}
  \end{align*}
  we have
  \begin{align*}
    \ensuremath{{\mathbb{P}}}\left( \max_{t \in [0, T_1]} h(\Gamma_t) \geq - \frac{1}{2}\left( \ensuremath{d}+1 \right)^{-1/q}  \right) \leq \exp(-\frac{2}{3} q\log(\ensuremath{d})) \leq \frac{3}{10}
  \end{align*}
  where $T_1 = \frac{1}{32768 q \alpha^2 \log(\ensuremath{d}) \ensuremath{d}^{2\beta}}$.

Under the same assumptions of Lemma~5, the potential $\Gamma_t$ defined in Equation~(14) can be written as follows
  \begin{align*}
    d\Gamma_t = v_t^\top dW_t + \delta_t dt,
  \end{align*}
  where $v_t \in \ensuremath{\mathbb{R}}^{\ensuremath{d}}$ and $\delta_t \in \ensuremath{\mathbb{R}}$ satisfy
  \begin{align*}
    \left\| v_t\right\|_{2} &\leq 16 q \Gamma_t^{1 + 1/(2q)}, \text{ and } \\
    \delta_t &\leq \min\left\{ 64 q^2 \alpha^2 \log(\ensuremath{d}) \ensuremath{d}^{2\beta -1/q}\Gamma_t^{1 + 1/q}, \frac{2q^2}{t} \Gamma_t \right \}.
  \end{align*}

Under the same assumptions of Lemma~6, using the following transformation
  \begin{align*}
    f: \ensuremath{\mathbb{R}}_+ &\rightarrow \ensuremath{\mathbb{R}} \\
    a &\mapsto a^{1/q}
  \end{align*}
  we have
  \begin{align*}
    \ensuremath{{\mathbb{E}}} f(\Gamma_{t_2}) \leq \ensuremath{{\mathbb{E}}} f(\Gamma_{t_1}) \left( \frac{t_2}{t_1} \right)^{2q}, \forall t_2 > t_1 > 0.
  \end{align*}

Suppose that $\psi_k \geq \frac{1}{\alpha k^\beta}$ for all $k \leq \ensuremath{d}$ for some $0 \leq \beta \leq \frac{1}{2}$ and $\alpha \geq 1$. Suppose $p$ is a log-concave density in $\ensuremath{\mathbb{R}}^{\ensuremath{d}}$ with covariance $A$ and $A$ is invertible. Then for $q \geq \frac{1}{2\beta}$, we have
  \begin{align*}
    \mathcal{T}_p(A^{q-2}, \ensuremath{\mathbb{I}}_{\ensuremath{d}}, \ensuremath{\mathbb{I}}_{\ensuremath{d}}) \leq 128 \alpha^2 \log(\ensuremath{d}) \ensuremath{d}^{2\beta - 1/q} \mathrm{Tr}(A^q) ^{1 + 1/q}.
  \end{align*}

Suppose $p$ is a log-concave density with mean $\mu$ and covariance $A$. Then for any positive semi-definite matrices $B$ and $C$, we have
  \begin{align*}
    \left\| \int B^{1/2} (x - \mu) (x - \mu) ^\top C (x - \mu) p(x)dx\right\|_{2} \leq 16 \left\| A^{1/2}B A^{1/2}\right\|_{2}^{1/2} \mathrm{Tr}\left( A^{1/2} C A^{1/2} \right)
  \end{align*}

Given $\tau > 0$. Suppose $p$ is a log-concave density which is more log-concave than $\ensuremath{\mathcal{N}}(0, \frac{1}{\tau} \ensuremath{\mathbb{I}}_{\ensuremath{d}})$. Let $A$ be its covariance matrix. Suppose $A$ is invertible then for $q \geq 3$, we have
  \begin{align*}
    \mathcal{T}_p(A^{q-2}, \ensuremath{\mathbb{I}}_{\ensuremath{d}}, \ensuremath{\mathbb{I}}_{\ensuremath{d}}) \leq \frac{4}{\tau} \mathrm{Tr}\left( A^{q} \right)
  \end{align*}
